fe.append_section(S, '02', '## Why the array forgets, and what SQL would change', """`createIssueRepository()` (`server/server.js:84`) keeps `issues` in a closure. Every request mutates that array synchronously, so within one process there is no interleaving and no need for a transaction. Two things follow. First, a restart reseeds: nothing you created survives, which is fine for a lesson and wrong for a product. Second, the filter in `list()` scans every issue and lower-cases the title, description and assignee on every request; with SQL that becomes `WHERE (status = $1 OR $1 = 'all') AND (priority = $2 OR $2 = 'all') AND (title ILIKE $3 OR ...)`, the case handling moves into the database, and the `priority` vocabulary check moves from `validateIssue` into a `CHECK` constraint or an enum type. What does *not* change is the shape of the guard: validate the query before you touch storage, and answer 400 for a vocabulary you do not know (the first test's `priority=Unknown`).""")
def patch_test(t):
    add = '''
test("search and priority compose to zero matches, and URL-encoded text is decoded before matching", async () => {
  assert.equal((await call("/api/issues", "POST", { ...valid, title: "Rendering & layout glitch", priority: "Critical" })).status, 201);
  const none = (await call("/api/issues?search=Rendering&priority=Low")).data;
  assert.equal(none.length, 0);
  const some = (await call("/api/issues?search=" + encodeURIComponent("Rendering & layout") + "&priority=Critical")).data;
  assert.equal(some.length, 1);
  assert.equal(some[0].title, "Rendering & layout glitch");
});
'''
    return t.rstrip('\n') + '\n' + add
